/-- Global finite-sample ninety-percent coverage. -/
def GlobalCoverage (n : ℕ) (α β : ℝ) (I : Procedure n) : Prop :=
  ∀ P, Model α β P → (9 / 10 : ℝ≥0∞) ≤
    experimentLaw P n {ω | effect P ∈ intervalSet (I.output ω)}

