/-- Infimum of worst-case length over globally honest procedures. -/
def lengthObjective (n : ℕ) (α β r : ℝ) : ℝ :=
  sInf {l | ∃ I : Procedure n, HonestProcedure n α β I ∧ l = worstLength n α β r I} -- @realizes J(minimax expected length)

