/-- Public exponent domain. -/
def ExponentDomain (α β : ℝ) : Prop :=
  0 < β ∧ β < 1 / 4 ∧ β < α ∧ α ≤ 1 -- @realizes \mathcal D(exact public exponent domain) @realizes \alpha(public real exponent) @realizes \beta(public real exponent)

